export function getLandmarkWikiStory(regionId, landmarkId) {
  const key = String(regionId || '').trim() + ':' + String(landmarkId || '').trim();
  const base = LANDMARK_WIKI_STORIES[key] || null;

  const hasManual = Object.prototype.hasOwnProperty.call(LANDMARK_WIKI_STORIES_MANUAL, key);
  if (!hasManual) return base;

  const rawManual = LANDMARK_WIKI_STORIES_MANUAL[key];
  if (rawManual == null) return null; // allow disabling a story via JSON

  // Allow manual JSON to provide either:
  // 1) fully built `introPagesUk/introPagesEn`, or
  // 2) builder input fields (`pageBodiesUk/pageBodiesEn/pageMedia`), from which we build the pages.
  const hasBuiltPages =
    Array.isArray(rawManual?.introPagesUk) || Array.isArray(rawManual?.introPagesEn);
  const hasBuilderInput =
    Array.isArray(rawManual?.pageBodiesUk) ||
    Array.isArray(rawManual?.pageBodiesEn) ||
    Array.isArray(rawManual?.pageMedia);

  if (!hasBuiltPages && hasBuilderInput) {
    try {
      const built = buildLandmarkIntroStory(rawManual);
      return { ...(base || {}), ...(built || {}) };
    } catch {
      // If build fails, fallback to the raw manual object.
      return { ...(base || {}), ...(rawManual || {}) };
    }
  }

  return { ...(base || {}), ...(rawManual || {}) };
}

export function landmarkWikiStoryKeys() {
  const out = new Set(Object.keys(LANDMARK_WIKI_STORIES));
  for (const k of Object.keys(LANDMARK_WIKI_STORIES_MANUAL || {})) out.add(k);
  return [...out];
}
